tool_and_message_events.command:
/bin/bash -lc 'set -eu
work="$(mktemp -d "$PWD/.catalog-review.XXXXXX")"
trap '"'rm -r -- \""'$work"'"' EXIT
cp -R review/base review/head \""'$work/"
cd "$work"
node --version
node --test base/test/catalog.test.mjs head/test/catalog.test.mjs
node --input-type=module <<'"'NODE'
import { copyFileSync, readFileSync } from 'node:fs';
import { spawnSync } from 'node:child_process';

for (const snapshot of ['base', 'head']) {
  const { loadCatalog, setPinned, saveCatalog } = await import("'`./${snapshot}/src/catalog.mjs`);
  for (const [operation, id, pinned, expected] of [
    ['"'pin Alpha', 'a', true, ['Alpha', 'Beta']],
    ['unpin Beta', 'b', false, []],
  ]) {
    const path = "'`./${snapshot}/catalog-check.json`;
    copyFileSync(`./${snapshot}/fixture/catalog.json`, path);
    saveCatalog(path, setPinned(loadCatalog(path), id, pinned));
    const reader = spawnSync(process.execPath, ['"'--input-type=module', '-e',
      "'`import { loadCatalog, pinnedTitles } from '"'./"'${snapshot}/src/catalog.mjs'"';
       console.log(JSON.stringify(pinnedTitles(loadCatalog(process.argv[1]))));"'`, path],
      { encoding: '"'utf8' });
    if (reader.status "'!== 0) throw new Error(reader.stderr);
    console.log(JSON.stringify({
      snapshot, operation, expected, actual: JSON.parse(reader.stdout),
      saved: JSON.parse(readFileSync(path, '"'utf8')),
    }));
  }
}
NODE"
